    एउटा stripslashes उदाहरण


<?php
$str = "Is your name O\'reilly?";

// Outputs: Is your name O'reilly?
echo stripslashes($str);
?>






stripslashes recursive हुँदैन। यदि तपाईँ यो function लाई multi-dimensional array मा लागू गर्न चाहनुहुन्छ भने, तपाईँले एउटा recursive function प्रयोग गर्नुपर्ने हुन्छ।




    एउटा array मा stripslashes को प्रयोग


<?php
function stripslashes_deep($value)
{
    $value = is_array($value) ?
                array_map('stripslashes_deep', $value) :
                stripslashes($value);

    return $value;
}

// Example
$array = array("f\\'oo", "b\\'ar", array("fo\\'o", "b\\'ar"));
$array = stripslashes_deep($array);

// Output
print_r($array);
?>


    &example.outputs;


Array
(
    [0] => f'oo
    [1] => b'ar
    [2] => Array
        (
            [0] => fo'o
            [1] => b'ar
        )

)
